def transform(grid):
    h,w=len(grid),len(grid[0])
    r=next((i for i,row in enumerate(grid) if len(set(row))==1),None)
    if r is not None:
        top,bottom=grid[:r],grid[r+1:]
    else:
        c=next(j for j in range(w) if len({grid[i][j] for i in range(h)})==1)
        top=[row[:c] for row in grid]; bottom=[row[c+1:] for row in grid]
    # Recolor the lower panel's background as 3 and its sparse marks as the
    # upper panel's background.
    counts={}
    for row in bottom:
        for x in row: counts[x]=counts.get(x,0)+1
    bg=max(counts,key=counts.get)
