def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    sep=next(r for r,row in enumerate(g) if all(x==2 for x in row))
    # The pattern in the lower field shifts upward until its top meets the
    # divider; recolor the original divider row 8.
    pts=[(r,c) for r in range(sep+1,h) for c in range(w) if g[r][c] not in (7,2)]
    if not pts: return g
    top=min(r for r,c in pts); bottom=max(r for r,c in pts)
    dr=sep+1-top
    pattern=[(r,c,g[r][c]) for r,c in pts]
    for r in range(sep,h):
        g[r]=[7]*w
